'use strict';
const fs=require('node:fs');
const path=require('node:path');
const repo=path.resolve(__dirname,'..');
const read=p=>fs.readFileSync(path.join(repo,p),'utf8');
const write=(p,s)=>fs.writeFileSync(path.join(repo,p),s,'utf8');
function replaceOnce(file,from,to){let s=read(file);if(!s.includes(from))throw new Error(`Pattern not found in ${file}: ${from.slice(0,80)}`);s=s.replace(from,to);write(file,s);}

