let css=read('uopt/styles.css');if(!css.includes('v0.1.7 translation transparency')) css += `\n/* v0.1.7 translation transparency */\n.uopt-select-wrap{position:relative;display:block;width:100%}\n.uopt-select-wrap::after{content:'▾';position:absolute;right:11px;top:50%;transform:translateY(-52%);pointer-events:none;color:var(--text-muted);font-size:.9em}\n.uopt-select{appearance:none!important;-webkit-appearance:none!important;padding-right:34px!important;cursor:pointer;background:var(--background-primary)!important;border:1px solid var(--background-modifier-border)!important}\n.uopt-select:hover{border-color:var(--background-modifier-border-hover)!important}\n.uopt-log-settings{margin-top:14px;padding-top:12px;border-top:1px solid var(--background-modifier-border)}\n.uopt-log-path{font-family:var(--font-monospace);font-size:var(--font-ui-smaller);color:var(--text-muted);overflow-wrap:anywhere;margin:5px 0 8px}\n.uopt-operation-attempt{margin-top:7px;font-weight:600;color:var(--text-normal)}\n.uopt-operation-log{margin-top:8px;padding-top:8px;border-top:1px solid var(--background-modifier-border)}\n.uopt-operation-log-actions{margin-top:6px}\n`;write('uopt/styles.css',css);

// Version metadata.
for(const f of ['PROJECT.json','uopt/package.json','uopt/manifest.json','uopt/package-lock.json']){const d=JSON.parse(read(f));d.version='0.1.7';if(d.packages&&d.packages[''])d.packages[''].version='0.1.7';write(f,JSON.stringify(d,null,2)+'\n');}
const versions=JSON.parse(read('uopt/versions.json'));versions['0.1.7']='1.7.2';write('uopt/versions.json',JSON.stringify(versions,null,2)+'\n');
replaceOnce('uopt/tests/versioning.test.js','all version metadata agrees on 0.1.6','all version metadata agrees on 0.1.7');
replaceOnce('uopt/tests/versioning.test.js',"assert.equal(project.version, '0.1.6');","assert.equal(project.version, '0.1.7');");
let changelog=read('CHANGELOG.md');if(!changelog.includes('## 0.1.7')) changelog=`## 0.1.7\n\n- Added live per-run translation logs under \`uopt/logs/\` with request, raw response, extracted output, parser result, telemetry, and append-only events.\n- Added run IDs, attempt/acceptance/unresolved counters, Ollama timing telemetry, and log-folder controls to the UI.\n- Added automatic OpenAI secret redaction and log retention (20 runs / 250 MB).\n- Fixed the Provider selector so it is visually obvious as a dropdown.\n\n`+changelog;write('CHANGELOG.md',changelog);

// v0.1.7 tests.
write('uopt/tests/logging-v017.test.js',`'use strict';\nconst test=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs/promises');const os=require('node:os');const path=require('node:path');const {TranslationRunLogger,redactSecrets}=require('../src/lib/run-logger');\ntest('redacts secrets recursively',()=>{const r=redactSecrets({headers:{Authorization:'Bearer sk-secret'},apiKey:'sk-other',token:'abc'});assert.equal(r.headers.Authorization,'[REDACTED]');assert.equal(r.apiKey,'[REDACTED]');assert.equal(r.token,'[REDACTED]');});\ntest('flushes full attempt artifacts while run is active',async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'uopt-log-'));const l=new TranslationRunLogger({baseDir:root,randomBytes:()=>Buffer.from('aabbcc','hex')});await l.start({pluginId:'canvas-enhance',provider:'Ollama',model:'qwen3.5:9b'});await l.writeCandidates('main.js',[{id:'c1',text:'通用'}],{sourceHash:'abc'});const ctx={file:'main.js',batch:1,totalBatches:4,attempt:1,maxAttempts:3,candidateCount:1};await l.recordAttemptRequest(ctx,{headers:{Authorization:'Bearer secret'},body:'x'});await l.recordAttemptResponse(ctx,{response:{message:{content:'c1\\tGeneral'}},output:'c1\\tGeneral',parse:{accepted:1,unresolved:0,acceptedIds:['c1'],unresolvedIds:[]}});const dir=path.join(l.runDir,'main.js','batch-01');assert.equal(JSON.parse(await fs.readFile(path.join(dir,'attempt-01.request.json'),'utf8')).headers.Authorization,'[REDACTED]');assert.match(await fs.readFile(path.join(dir,'attempt-01.output.txt'),'utf8'),/General/);assert.equal(JSON.parse(await fs.readFile(path.join(dir,'attempt-01.parse.json'),'utf8')).accepted,1);assert.match(await fs.readFile(path.join(l.runDir,'events.jsonl'),'utf8'),/attempt_response/);});\n`);
write('uopt/tests/provider-logging-v017.test.js',`'use strict';\nconst test=require('node:test');const assert=require('node:assert/strict');const {OllamaProvider}=require('../src/lib/providers');\ntest('Ollama logs and reports each protocol attempt',async()=>{const calls=[],progress=[];const logger={recordAttemptRequest:async(c,r)=>calls.push(['request',c,r]),recordAttemptResponse:async(c,r)=>calls.push(['response',c,r])};let n=0;const p=new OllamaProvider({baseUrl:'http://localhost:11434',model:'qwen3.5:9b',maxProtocolAttempts:2,runLogger:logger,request:async()=>({json:{message:{content:++n===1?'garbage':'c1\\tGeneral'},prompt_eval_count:10,eval_count:5,total_duration:100}})});const result=await p.translate({},[{id:'c1',text:'通用'}],{file:'main.js',batch:2,totalBatches:4,onAttempt:i=>progress.push(i)});assert.equal(result.get('c1'),'General');assert.equal(calls.filter(x=>x[0]==='request').length,2);assert.equal(calls.filter(x=>x[0]==='response').length,2);assert.equal(calls.find(x=>x[0]==='response')[2].parse.unresolved,1);assert.equal(progress.at(-1).unresolved,0);});\n`);
write('uopt/tests/ui-transparency-v017.test.js',`'use strict';\nconst test=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');const root=path.resolve(__dirname,'..');\ntest('v0.1.7 exposes obvious provider select and log controls',()=>{const s=fs.readFileSync(path.join(root,'src/lib/settings-tab.js'),'utf8'),css=fs.readFileSync(path.join(root,'styles.css'),'utf8');assert.match(s,/uopt-select-wrap/);assert.match(s,/Open logs folder/);assert.match(s,/Copy logs path/);assert.match(s,/Clear logs/);assert.match(css,/\\.uopt-select-wrap::after/);});\ntest('operation feedback exposes attempt and parser counts',()=>{const s=fs.readFileSync(path.join(root,'src/main.js'),'utf8');assert.match(s,/Attempt \\$\\{operation\\.attempt\\}/);assert.match(s,/accepted/);assert.match(s,/unresolved/);assert.match(s,/Open log folder/);});\n`);
